"""The tp4/prefill-2 window pack (scripts/ci/references/fusion-jobs/PF2, generated by make_pf2_jobs.py) and the report that reads its pairs (pf2_report).

ORDER.txt lists exactly the folder's templates, each once, on the one image, with a total that matches its header; every NEEDS line names earlier jobs; every smoke job carries the two Swift checkpoint keys
and the same profile as its pair partner but for the flag; every prefix job runs a twin of the family on the tier-timed plan and carries no checkpoint key (the prefix step does not forward it); every template
parses through the job reader with rc 0 and no refusal; the pack is what the generator makes; nothing in it names a host, an address or a registry. pf2_report reads the pair the way the templates say."""

import contextlib
import io
import json
import os
from pathlib import Path
import re
import subprocess
import sys
import tempfile
import unittest

HERE = Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

import c2_serving_job as job  # noqa: E402
import make_pf2_jobs as pack  # noqa: E402
import pf2_report as report  # noqa: E402
import prefill_handoff  # noqa: E402

PACK = pack.FOLDER
READER = HERE / 'c2_serving_job.py'
PROFILES = HERE / 'qwen_c2_profiles.json'
CATALOG = json.loads((HERE / 'qwen_c2_checkpoints.json').read_text(encoding='utf-8'))
SWIFT = CATALOG['checkpoints'][0]

# job -> (mode, serves Swift, profile, smoke tests, prefix plan)
EXPECTED = {
    'B0-build-window': ('stop', False, '', '', ''),
    'X0-status-rescan-reset': ('stop', False, '', '', ''),
    'A1-pf2-audited-attach': ('stop', True, pack.AUDIT, pack.SMOKE_TESTS, ''),
    'AP1-pf2-audited-returning': ('stop', False, '', '', 'tier-timed'),
    'T1-ctl-a': ('soft', True, pack.CONTROL, pack.TIMED_TESTS, ''),
    'T2-pf2-a': ('soft', True, pack.ARM, pack.TIMED_TESTS, ''),
    'T3-ctl-b': ('soft', True, pack.CONTROL, pack.TIMED_TESTS, ''),
    'T4-pf2-b': ('soft', True, pack.ARM, pack.TIMED_TESTS, ''),
    'R1-ctl-returning': ('soft', False, '', '', 'tier-timed'),
    'R2-pf2-returning': ('soft', False, '', '', 'tier-timed'),
    'Z-reset': ('soft', False, '', '', ''),
}
PREFIX_PROFILES = {'AP1-pf2-audited-returning': pack.AUDIT, 'R1-ctl-returning': pack.CONTROL, 'R2-pf2-returning': pack.ARM}


def order_lines():
    return [line.split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.strip() and not line.startswith('#')]


def directives(prefix):
    return [line[len(prefix):].split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.startswith(prefix)]


def values(name):
    return job.parse_env((PACK / (name + '.env')).read_text(encoding='utf-8'))


def run_reader(path):
    result = subprocess.run([sys.executable, '-B', '-s', str(READER), str(path), str(PROFILES)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(HERE.parent.parent))
    return result.returncode, (result.stdout + result.stderr).decode('utf-8', 'replace'), result.stderr.decode('utf-8', 'replace')


class OrderTests(unittest.TestCase):
    def test_order_lists_exactly_the_folders_templates_once_on_one_image(self):
        rows = order_lines()
        self.assertEqual([row[0] for row in rows], list(EXPECTED), 'in value order')
        self.assertEqual(sorted(path.stem for path in PACK.glob('*.env')), sorted(EXPECTED))
        self.assertEqual({row[2] for row in rows}, {pack.IMAGE})
        self.assertEqual(pack.IMAGE, 'tp4-pf2-1', 'the placeholder tag of the pack')
        for row in rows:
            self.assertEqual(row[1], EXPECTED[row[0]][0], row[0])
            self.assertEqual(values(row[0])['C2_IMAGE_TAG'], pack.IMAGE)

    def test_the_header_total_matches_the_minutes(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        minutes = sum(int(row[3]) for row in order_lines())
        self.assertIn('%d minutes (%d h %d min) in all' % (minutes, minutes // 60, minutes % 60), text)
        for row in order_lines():
            self.assertIn('%s %s' % (row[0].split('-')[0], row[3]), text)

    def test_needs_lines_name_earlier_jobs_only(self):
        names = [row[0].split('-')[0] for row in order_lines()]
        for left_right in directives('# NEEDS '):
            arrow = left_right.index('<-')
            left, right = left_right[:arrow], left_right[arrow + 1:]
            for job_name in left + right:
                self.assertIn(job_name, names)
            for later in left:
                for earlier in right:
                    self.assertLess(names.index(earlier), names.index(later), left_right)
        needed = set(token for line in directives('# NEEDS ') for token in line[:line.index('<-')])
        self.assertTrue({'X0', 'A1', 'AP1', 'T1', 'T2', 'T3', 'T4', 'R1', 'R2'} <= needed)
        self.assertIn(['T1', '<-', 'A1', 'AP1'], directives('# NEEDS '), 'no timing before both exactness gates passed')

    def test_the_arc_range_covers_the_audited_boot_and_every_timed_job_and_nothing_else(self):
        names = [row[0].split('-')[0] for row in order_lines()]
        (first, last), = directives('# ARC-ZERO ')
        self.assertEqual((first, last), ('A1', 'R2'))
        for token in ('A1', 'AP1', 'T1', 'T2', 'T3', 'T4', 'R1', 'R2'):
            self.assertTrue(names.index(first) <= names.index(token) <= names.index(last), token)
        for token in ('B0', 'X0', 'Z'):
            self.assertFalse(names.index(first) <= names.index(token) <= names.index(last), token)

    def test_no_tag_is_pushed_from_the_branch_and_the_order_says_what_is_new_on_the_device(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        for phrase in ('Never cancel a running card job', 'THE ONE NEW DEVICE FACT', 'UNQUALIFIED', 'owner traffic waiver', '48.6 ms', '115.2 ms'):
            self.assertIn(phrase, text)
        for name in EXPECTED:
            self.assertIn('no tag is pushed from the branch by its author', (PACK / (name + '.env')).read_text(encoding='utf-8'))


class TemplateTests(unittest.TestCase):
    def test_every_template_parses_with_rc_0_and_no_refusal(self):
        for name in EXPECTED:
            with self.subTest(name=name):
                code, text, errors = run_reader(PACK / (name + '.env'))
                self.assertEqual(code, 0, text)
                self.assertNotIn('refused', errors)

    def test_smoke_jobs_carry_the_checkpoint_keys_and_the_expected_profile_and_tests(self):
        for name, (_mode, serves_swift, profile, tests, plan) in EXPECTED.items():
            with self.subTest(name=name):
                found = values(name)
                if serves_swift:
                    self.assertEqual((found['C2_MODEL_REPO'], found['C2_MODEL_REVISION']), (SWIFT['repo'], SWIFT['revision']))
                    self.assertEqual((pack.REPO, pack.REVISION), (SWIFT['repo'], SWIFT['revision']))
                else:
                    self.assertNotIn('C2_MODEL_REPO', found)
                    self.assertNotIn('C2_MODEL_REVISION', found)
                self.assertEqual(found.get('C2_PROFILE', ''), profile)
                self.assertEqual(found.get('C2_SMOKE_TESTS', ''), tests)
                self.assertEqual(found.get('C2_PREFIX_PLAN', ''), plan)

    def test_the_outputs_the_workflow_reads(self):
        for name, (_mode, serves_swift, _profile, _tests, _plan) in EXPECTED.items():
            code, text, _errors = run_reader(PACK / (name + '.env'))
            outputs = dict(line.split('=', 1) for line in text.splitlines() if '=' in line)
            with self.subTest(name=name):
                self.assertEqual(outputs['model_repo'], SWIFT['repo'] if serves_swift else '')

    def test_each_smoke_job_names_the_steady_test_and_a_box_inside_the_step(self):
        for name in EXPECTED:
            found = values(name)
            if 'smoke' not in found['C2_ACTIONS'].split():
                continue
            with self.subTest(name=name):
                self.assertIn('concurrent8_steady', found['C2_SMOKE_TESTS'].split(','))
                self.assertIn('prefill_ladder_solo', found['C2_SMOKE_TESTS'].split(','))
                self.assertTrue(0 < int(found['C2_BOX_MINUTES']) <= 210)
                self.assertEqual(found['C2_CARDS'], 'quad')
                self.assertEqual(found['C2_TELEMETRY'], '1')

    def test_the_prefix_jobs_run_a_twin_on_the_tier_timed_plan_without_a_baseline_or_a_checkpoint_key(self):
        for name, profile in PREFIX_PROFILES.items():
            with self.subTest(name=name):
                found = values(name)
                self.assertEqual(found['C2_ACTIONS'], 'reset prefix')
                self.assertEqual((found['C2_PREFIX_PLAN'], found['C2_PREFIX_PROFILE'], found['C2_PREFIX_BASELINE']), ('tier-timed', profile, 'none'))
                self.assertNotIn('C2_MODEL_REPO', found)

    def test_no_model_job_uses_a_step_that_does_not_forward_the_checkpoint(self):
        for name in EXPECTED:
            actions = set(values(name)['C2_ACTIONS'].split())
            if values(name).get('C2_MODEL_REPO'):
                self.assertFalse(actions - set(job.MODEL_ACTIONS), name)
            self.assertFalse(actions & {'gate', 'replay', 'push', 'agentstop', 'agentstart', 'unserve', 'platform'}, name)

    def test_the_build_bakes_the_approved_ship_profile_with_the_oneq_graft_and_never_a_twin(self):
        found = values('B0-build-window')
        self.assertEqual((found['C2_BAKE_DEFAULT_PROFILE'], found['C2_BAKE_GRAFT']), (pack.SHIP, 'K64j-OQ'))
        entry = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles'][pack.SHIP]
        self.assertFalse(job.bake_waiver_pending(entry), 'the ship-4 waiver is APPROVED: the build is not refused')
        self.assertNotIn(pack.ARM, json.dumps(found))
        for name in EXPECTED:
            if name != 'B0-build-window':
                self.assertNotIn('C2_BAKE_DEFAULT_PROFILE', values(name), name)

    def test_the_pairs_differ_by_the_profile_alone_and_the_control_is_the_flag_at_zero(self):
        keys = ('C2_SMOKE_TESTS', 'C2_BOX_MINUTES', 'C2_IMAGE_TAG', 'C2_MODEL_REPO', 'C2_MODEL_REVISION', 'C2_CARDS', 'C2_ACTIONS', 'C2_TELEMETRY')
        for control, arm in (('T1-ctl-a', 'T2-pf2-a'), ('T3-ctl-b', 'T4-pf2-b')):
            self.assertEqual([values(control)[key] for key in keys], [values(arm)[key] for key in keys])
            self.assertEqual((values(control)['C2_PROFILE'], values(arm)['C2_PROFILE']), (pack.CONTROL, pack.ARM))
        keys = ('C2_ACTIONS', 'C2_IMAGE_TAG', 'C2_CARDS', 'C2_PREFIX_PLAN', 'C2_PREFIX_BASELINE', 'C2_BOX_MINUTES')
        self.assertEqual([values('R1-ctl-returning')[key] for key in keys], [values('R2-pf2-returning')[key] for key in keys])
        profiles = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles']
        self.assertEqual(profiles[pack.CONTROL]['env'][prefill_handoff.FLAG], '0')
        self.assertEqual(profiles[pack.ARM]['env'][prefill_handoff.FLAG], '1')
        self.assertEqual(profiles[pack.AUDIT]['env'][prefill_handoff.AUDIT_FLAG], '1')

    def test_the_audited_attach_runs_the_audit_twin_and_a_box_longer_than_its_estimate(self):
        found = values('A1-pf2-audited-attach')
        self.assertEqual(found['C2_PROFILE'], pack.AUDIT)
        self.assertLessEqual(int(found['C2_BOX_MINUTES']), 210)
        self.assertGreater(int(found['C2_BOX_MINUTES']), int(order_lines()[2][3]), 'the box is longer than the estimate')

    def test_the_templates_name_the_lines_the_arms_log_and_the_tools_that_read_them(self):
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'T2-pf2-a.env').read_text(encoding='utf-8'))
        for phrase in ('[PINDIAG] prefill handoff engaged mode=device layers=48 clones=240', '[PF2] handoff mode=device', '[PF2] handoff mode=host', 'pf2_report.py', 'prefill_ladder_report.py', 'handoff=device'):
            self.assertIn(phrase, text)
        audited = re.sub(r'\s*\n#\s*', ' ', (PACK / 'A1-pf2-audited-attach.env').read_text(encoding='utf-8'))
        for phrase in ('audit n=<k> exact=True', 'audit mismatch', 'handoff=device audit'):
            self.assertIn(phrase, audited)

    def test_the_lines_the_templates_name_are_the_lines_the_module_and_the_route_print(self):
        self.assertEqual(prefill_handoff.ENGAGED_MARKER, '[PINDIAG] prefill handoff engaged')
        self.assertEqual(prefill_handoff.TIMING_MARKER, '[PF2] handoff')
        self.assertEqual(report.ENGAGED, prefill_handoff.ENGAGED_MARKER)
        self.assertEqual(report.FELL_BACK, prefill_handoff.FELL_BACK_MARKER)
        self.assertEqual(report.MISMATCH, prefill_handoff.AUDIT_MISMATCH_MARKER)


class GeneratedTests(unittest.TestCase):
    def test_the_checked_in_pack_is_what_the_generator_makes(self):
        self.assertEqual(pack.main(['--check']), 0)

    def test_nothing_in_the_pack_names_a_host_an_address_or_a_registry(self):
        for path in PACK.glob('*'):
            text = path.read_text(encoding='utf-8')
            with self.subTest(path=path.name):
                self.assertEqual([needle for needle in ('/home/', 'zot.', 'ghcr', 'docker.io', '.local', '.internal', 'localhost') if needle in text], [])
                self.assertIsNone(re.search(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', text), 'an IP address')
                self.assertIsNone(re.search(r'blackhole-[0-9A-F]{16}', text), 'a card id')
                self.assertIsNone(re.search(r'\bsha256:[0-9a-f]{12,}', text), 'an image digest')


# -- the report ----------------------------------------------------------------------------------------------------------------------------------------

def handoff_line(mode, ms, read=0.0, clone=None, write=None):
    write = ms - read - (clone or 0.0) if write is None else write
    return '[PF2] handoff mode=%s ms=%.1f read_ms=%.1f%s write_ms=%.1f layers=48' % (mode, ms, read, '' if clone is None else ' clone_ms=%.1f' % clone, write)


def route_line(start, ms, final=1):
    return '[PINDIAG] lever N route req=r%d start=%d end=%d prompt=%d final=%d wrote_slot=%d ms=%.1f programs=2400->2400 window=0' % (start, start, start + 2048, start + 2048, final, final, ms)


class ReportTests(unittest.TestCase):
    def logs(self, control_lines, arm_lines):
        directory = tempfile.mkdtemp()
        self.addCleanup(lambda: [os.unlink(os.path.join(directory, name)) for name in os.listdir(directory)] and os.rmdir(directory))
        paths = []
        for name, lines in (('control.log', control_lines), ('arm.log', arm_lines)):
            path = os.path.join(directory, name)
            with open(path, 'w', encoding='utf-8') as handle:
                handle.write('\n'.join(lines) + '\n')
            paths.append(path)
        return paths

    def good(self):
        control = [handoff_line('host', 90.0 + index, read=40.0, write=50.0 + index) for index in range(10)] + [route_line(130000 + 2048 * index, 1200.0) for index in range(10)]
        arm = ['[PINDIAG] prefill handoff engaged mode=device layers=48 clones=240'] + [handoff_line('device', 45.0 + index, clone=15.0, write=30.0 + index) for index in range(10)] + [route_line(130000 + 2048 * index, 1150.0) for index in range(10)]
        return control, arm

    def test_a_pair_reads_the_saving_per_final_step_and_the_bands(self):
        control, arm = (report.read([path]) for path in self.logs(*self.good()))
        summary = report.summarise(control, arm)
        self.assertEqual(summary['problems'], [])
        self.assertAlmostEqual(summary['saving_ms_per_final_step'], 45.0, places=1)
        self.assertEqual(summary['control']['n'], 10)
        self.assertEqual(summary['routes']['arm']['96-160k']['n'], 10)
        self.assertEqual(summary['routes']['control']['96-160k']['mean'], 1200.0)
        with contextlib.redirect_stdout(io.StringIO()):
            self.assertEqual(report.main(['--control', self.logs(*self.good())[0], '--arm', self.logs(*self.good())[1]]), 0)

    def test_two_logs_of_one_arm_are_one_population(self):
        control_lines, arm_lines = self.good()
        control_paths, arm_paths = self.logs(control_lines, arm_lines), self.logs(control_lines, arm_lines)
        merged = report.read([control_paths[0], arm_paths[0]])
        self.assertEqual(len(merged['handoff']), 20)

    def test_an_arm_that_never_engaged_a_fallback_a_mismatch_or_a_control_that_ran_the_lever_is_not_a_pair(self):
        control_lines, arm_lines = self.good()
        cases = (('no engaged line', control_lines, arm_lines[1:], 'engaged'),
                 ('a fell-back line', control_lines, arm_lines + ['[PINDIAG] prefill handoff fell back reason=RuntimeError: x'], 'fell back'),
                 ('an audit mismatch', control_lines, arm_lines + ['[PINDIAG] prefill handoff audit mismatch n=3 exact=False'], 'mismatch'),
                 ('an inexact audit line', control_lines, arm_lines + ['[PINDIAG] prefill handoff audit n=3 exact=False slot=1'], 'mismatch'),
                 ('a control that engaged', control_lines + ['[PINDIAG] prefill handoff engaged mode=device layers=48 clones=240'], arm_lines, 'control logged'),
                 ('a control that timed the device path', control_lines + [handoff_line('device', 40.0, clone=10.0)], arm_lines, 'host path alone'),
                 ('an arm with no device timing', control_lines, arm_lines[:1] + [handoff_line('host', 90.0, read=40.0)] + arm_lines[11:], 'no device hand-off'))
        for word, control_extra, arm_extra, needle in cases:
            with self.subTest(word):
                summary = report.summarise(*(report.read([path]) for path in self.logs(control_extra, arm_extra)))
                self.assertTrue(any(needle in problem for problem in summary['problems']), summary['problems'])
        with contextlib.redirect_stdout(io.StringIO()):
            self.assertEqual(report.main(['--control', self.logs(*self.good())[0], '--arm', self.logs(control_lines, arm_lines[1:])[1]]), 1)

    def test_a_missing_log_is_exit_2_and_the_json_form_parses(self):
        with contextlib.redirect_stderr(io.StringIO()):
            self.assertEqual(report.main(['--control', '/nonexistent/control.log', '--arm', '/nonexistent/arm.log']), 2)
        control, arm = self.logs(*self.good())
        completed = subprocess.run([sys.executable, '-B', str(HERE / 'pf2_report.py'), '--control', control, '--arm', arm, '--json'], stdout=subprocess.PIPE, check=True)
        self.assertAlmostEqual(json.loads(completed.stdout.decode('utf-8'))['saving_ms_per_final_step'], 45.0, places=1)

    def test_the_regexes_read_the_lines_the_module_and_the_route_print(self):
        import levern_policy

        sample = levern_policy.ROUTE_LINE.format('abc', 125952, 128000, 129616, 1, 1, 1180.2, 2400, 2400, 0)
        self.assertEqual(report.ROUTE.search(sample).groups(), ('125952', '128000', '129616', '1', '1', '1180.2'))
        host = '%s mode=host ms=%.1f read_ms=%.1f write_ms=%.1f layers=%d' % (prefill_handoff.TIMING_MARKER, 90.0, 40.0, 50.0, 48)
        device = '%s mode=device ms=%.1f read_ms=0.0 clone_ms=%.1f write_ms=%.1f layers=%d' % (prefill_handoff.TIMING_MARKER, 45.0, 15.0, 30.0, 48)
        self.assertEqual(report.HANDOFF.search(host).groups(), ('host', '90.0', '40.0', None, '50.0', '48'))
        self.assertEqual(report.HANDOFF.search(device).groups(), ('device', '45.0', '0.0', '15.0', '30.0', '48'))


if __name__ == '__main__':
    unittest.main()
